import { Injectable } from '@angular/core';

import IcoMoonSelection from '../assets/selection.json'; // todo: lazy load this
import { Page } from 'espd-common/data';

/**
 * Only provide this service where absolutely necessary. The selection.json file it imports is very large.
 */
@Injectable()
export class IconService {

	static defaultPageSize: number = 36;

	private cachedIconList?: string[];


	public getIconList(): string[] {
		if (!this.cachedIconList) {
			this.cachedIconList = this.readIconList();
		}

		return this.cachedIconList;
	}

	// paging is 1-based
	public getPage(pageNum: number, pageSize: number, filter?: string, includeEmpty: boolean = false): Page<string> {
		pageSize = pageSize || IconService.defaultPageSize;

		const filteredList = this.getFilteredList(filter, includeEmpty);
		const start = (pageNum - 1) * pageSize;
		const end = start + pageSize;
		const content = filteredList.slice(start, end);
		const numPages = Math.ceil(filteredList.length / (pageSize || IconService.defaultPageSize));

		return {
			content,
			first: pageNum === 1,
			hasNext: pageNum < numPages,
			hasPrevious: pageNum > 1,
			last: pageNum === numPages,
			number: numPages > 0 ? pageNum : 0,
			numberOfElements: content.length,
			size: pageSize,
			totalElements: filteredList.length,
			totalPages: numPages
		};
	}

	public getPageForIcon(icon: string, pageSize: number = IconService.defaultPageSize): number {
		const fullList = this.getFilteredList('', true);
		let index = fullList.indexOf(icon);
		if (index < 0) {
			index = 0;
		}
		return Math.floor(index / pageSize) + 1;
	}

	private getFilteredList(term: string = '', includeEmpty: boolean = false): string[] {
		term = term.toLocaleLowerCase();
		let fullList = (includeEmpty ? ['empty'] : []).concat(this.getIconList());
		if (term) {
			fullList = fullList.filter(icon => icon.toLocaleLowerCase().includes(term));
		}
		return fullList;
	}

	private readIconList(): string[] {
		return IcoMoonSelection.icons.map(i => i.properties.name);
	}
}
